var scene=UnityEditor.SceneManagement.EditorSceneManager.OpenScene("Assets/Scenes/GameScane.unity",UnityEditor.SceneManagement.OpenSceneMode.Additive);try{return scene.GetRootGameObjects().SelectMany(x=>x.GetComponentsInChildren<RectTransform>(true)).Where(x=>x.name.IndexOf("Health",System.StringComparison.OrdinalIgnoreCase)>=0||x.name.IndexOf("Heart",System.StringComparison.OrdinalIgnoreCase)>=0||x.name=="GameSpeedControls"||x.name=="GoldBar"||x.name=="PreparationCountdown"||x.GetComponent<UİManager>()!=null).Select(x=>new{name=x.name,parent=x.parent!=null?x.parent.name:null,position=x.anchoredPosition.ToString(),rect=x.rect.ToString(),canvas=x.GetComponentInParent<Canvas>()!=null?x.GetComponentInParent<Canvas>().name:null}).ToArray();}finally{UnityEditor.SceneManagement.EditorSceneManager.CloseScene(scene,true);}
